CREATE OR REPLACE FUNCTION core.enforce_service_credential_account()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    PERFORM 1 FROM core.accounts WHERE id = NEW.account_id AND account_type IN ('service', 'system') FOR SHARE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Service credential requires a machine account' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION core.prevent_human_service_credentials()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.account_type = 'human' AND EXISTS (SELECT 1 FROM core.service_credentials WHERE account_id = NEW.id) THEN
        RAISE EXCEPTION 'Machine credentials cannot belong to a human account' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION core.protect_dsar_deadline()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF current_setting('app.privacy_lifecycle', true) = 'on' THEN RETURN OLD; END IF;
        RAISE EXCEPTION 'Deadline evidence cannot be deleted' USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.id, NEW.request_id, NEW.deadline_code, NEW.triggered_at, NEW.calendar_type,
        NEW.due_at, NEW.extension_allowed, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.request_id, OLD.deadline_code, OLD.triggered_at, OLD.calendar_type,
        OLD.due_at, OLD.extension_allowed, OLD.created_at) THEN
        RAISE EXCEPTION 'Original deadline evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.extended_at IS NOT NULL AND (NEW.extended_at, NEW.extended_due_at, NEW.extension_reason_code)
       IS DISTINCT FROM (OLD.extended_at, OLD.extended_due_at, OLD.extension_reason_code) THEN
        RAISE EXCEPTION 'Deadline cannot be extended twice' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.satisfied_at IS NOT NULL AND NEW.satisfied_at IS DISTINCT FROM OLD.satisfied_at THEN
        RAISE EXCEPTION 'Deadline satisfaction is immutable' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_dsar_event()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' AND current_setting('app.privacy_lifecycle', true) = 'on' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'Request workflow events are immutable' USING ERRCODE = 'check_violation';
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_dsar_execution()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        IF current_setting('app.privacy_lifecycle', true) = 'on' THEN RETURN OLD; END IF;
        RAISE EXCEPTION 'Execution evidence cannot be deleted' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status <> 'started' THEN
        RAISE EXCEPTION 'Terminal execution evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.id, NEW.request_id, NEW.execution_code, NEW.actor_account_id, NEW.contributor_code,
        NEW.resource_type, NEW.resource_id, NEW.started_at, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.request_id, OLD.execution_code, OLD.actor_account_id, OLD.contributor_code,
        OLD.resource_type, OLD.resource_id, OLD.started_at, OLD.created_at) THEN
        RAISE EXCEPTION 'Execution identity is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status = 'started' THEN
        RAISE EXCEPTION 'Execution may only move to a terminal result' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_legal_representation()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Legal representation evidence cannot be deleted outside privacy erasure' USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.id, NEW.subject_person_id, NEW.representative_person_id, NEW.authority_type,
        NEW.valid_from, NEW.valid_until, NEW.evidence_type, NEW.evidence_reference,
        NEW.evidence_sha256, NEW.created_at)
       IS DISTINCT FROM
       (OLD.id, OLD.subject_person_id, OLD.representative_person_id, OLD.authority_type,
        OLD.valid_from, OLD.valid_until, OLD.evidence_type, OLD.evidence_reference,
        OLD.evidence_sha256, OLD.created_at) THEN
        RAISE EXCEPTION 'Legal representation evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status IN ('revoked', 'rejected', 'expired') OR
       (OLD.status = 'verified' AND NEW.status NOT IN ('verified', 'revoked', 'expired')) THEN
        RAISE EXCEPTION 'Legal representation cannot be reactivated' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_legal_representation_scope()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE authority_status varchar(32);
BEGIN
    IF TG_OP = 'UPDATE' THEN
        RAISE EXCEPTION 'Authority scope evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    SELECT status INTO authority_status FROM core.legal_representations
    WHERE id = COALESCE(NEW.representation_id, OLD.representation_id) FOR UPDATE;
    IF authority_status NOT IN ('declared', 'verification_pending') THEN
        RAISE EXCEPTION 'Verified authority scopes cannot be changed' USING ERRCODE = 'check_violation';
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_privacy_consent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Consent evidence requires controlled privacy erasure' USING ERRCODE = 'check_violation';
    END IF;
    IF (NEW.id, NEW.granted_by_account_id, NEW.subject_person_id, NEW.granted_by_person_id,
        NEW.legal_representation_id, NEW.purpose_code, NEW.consent_code, NEW.document_version,
        NEW.document_sha256, NEW.locale, NEW.source, NEW.granted_at, NEW.request_id,
        NEW.created_at, NEW.legacy_record, NEW.retention_until)
       IS DISTINCT FROM
       (OLD.id, OLD.granted_by_account_id, OLD.subject_person_id, OLD.granted_by_person_id,
        OLD.legal_representation_id, OLD.purpose_code, OLD.consent_code, OLD.document_version,
        OLD.document_sha256, OLD.locale, OLD.source, OLD.granted_at, OLD.request_id,
        OLD.created_at, OLD.legacy_record, OLD.retention_until) THEN
        RAISE EXCEPTION 'Consent evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL OR NEW.withdrawn_at < OLD.granted_at THEN
        RAISE EXCEPTION 'Only an active consent may be withdrawn once' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_privacy_destruction_evidence()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' AND current_setting('app.privacy_lifecycle', true) = 'on' THEN RETURN OLD; END IF;
    RAISE EXCEPTION 'Destruction evidence is immutable' USING ERRCODE = 'check_violation';
END;
$function$

CREATE OR REPLACE FUNCTION core.protect_privacy_distribution_consent()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Distribution consent evidence is immutable' USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.withdrawn_at IS NOT NULL OR NEW.withdrawn_at IS NULL
       OR (to_jsonb(NEW) - 'withdrawn_at') IS DISTINCT FROM (to_jsonb(OLD) - 'withdrawn_at') THEN
        RAISE EXCEPTION 'Distribution consent may only be withdrawn once' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

