CREATE OR REPLACE FUNCTION core.validate_dsar_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actor_person uuid;
BEGIN
    SELECT person_id INTO actor_person FROM core.accounts
    WHERE id = NEW.submitted_by_account_id AND account_type = 'human';
    IF actor_person IS NULL THEN
        RAISE EXCEPTION 'Request actor must be a human Account' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.intake_channel IS NOT NULL THEN RETURN NEW; END IF;
    IF actor_person <> NEW.submitted_by_person_id THEN
        RAISE EXCEPTION 'Request actor must match human Account' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.legal_representation_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM core.legal_representations r
        WHERE r.id = NEW.legal_representation_id AND r.subject_person_id = NEW.subject_person_id
          AND r.representative_person_id = NEW.submitted_by_person_id
    ) THEN
        RAISE EXCEPTION 'Request representation does not match subject and actor' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION core.validate_legal_representation_verification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.status = 'verified' AND OLD.status <> 'verified' THEN
        IF NEW.verified_at IS NULL OR NEW.valid_from > NEW.verified_at
           OR (NEW.valid_until IS NOT NULL AND NEW.valid_until < NEW.verified_at) THEN
            RAISE EXCEPTION 'Authority is outside its validity interval' USING ERRCODE = 'check_violation';
        END IF;
        IF NOT EXISTS (SELECT 1 FROM core.legal_representation_scopes WHERE representation_id = NEW.id) THEN
            RAISE EXCEPTION 'Verified authority requires explicit scopes' USING ERRCODE = 'check_violation';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.validate_privacy_block_request()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.source_request_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM core.data_subject_requests
        WHERE id = NEW.source_request_id AND subject_person_id = NEW.subject_person_id
    ) THEN
        RAISE EXCEPTION 'Block source request belongs to another subject' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION core.validate_privacy_consent_insert()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE actor_person uuid;
BEGIN
    IF NEW.legacy_record THEN
        RAISE EXCEPTION 'New legacy consent evidence is forbidden' USING ERRCODE = 'check_violation';
    END IF;
    SELECT person_id INTO actor_person FROM core.accounts
    WHERE id = NEW.granted_by_account_id AND account_type = 'human';
    IF actor_person IS NULL OR actor_person <> NEW.granted_by_person_id THEN
        RAISE EXCEPTION 'Consent actor does not match human Account' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.subject_person_id <> NEW.granted_by_person_id AND NOT EXISTS (
        SELECT 1 FROM core.legal_representations r
        JOIN core.legal_representation_scopes s ON s.representation_id = r.id
        WHERE r.id = NEW.legal_representation_id
          AND r.subject_person_id = NEW.subject_person_id
          AND r.representative_person_id = NEW.granted_by_person_id
          AND s.scope_code = 'privacy.consent.grant'
          AND r.status = 'verified' AND r.verified_at IS NOT NULL AND r.revoked_at IS NULL
          AND r.valid_from <= NEW.granted_at
          AND (r.valid_until IS NULL OR r.valid_until >= NEW.granted_at)
    ) THEN
        RAISE EXCEPTION 'Consent grant scope is not active' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_runtime.protect_entitlement_document()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    last_sequence bigint;
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Entitlement snapshots cannot be deleted';
    END IF;

    IF TG_OP = 'UPDATE' THEN
        IF (NEW.id, NEW.installation_id, NEW.document_version, NEW.sequence,
            NEW.issued_at, NEW.valid_from, NEW.valid_until, NEW.payload,
            NEW.signature, NEW.signing_key_id, NEW.created_at)
           IS DISTINCT FROM
           (OLD.id, OLD.installation_id, OLD.document_version, OLD.sequence,
            OLD.issued_at, OLD.valid_from, OLD.valid_until, OLD.payload,
            OLD.signature, OLD.signing_key_id, OLD.created_at) THEN
            RAISE EXCEPTION 'Signed entitlement snapshot is immutable';
        END IF;
        IF OLD.status <> 'pending' THEN
            RAISE EXCEPTION 'Applied or rejected entitlement is immutable';
        END IF;
        IF OLD.status = 'pending' AND NEW.status = 'pending' AND NEW.applied_at IS DISTINCT FROM OLD.applied_at THEN
            RAISE EXCEPTION 'Pending entitlement cannot have an application time';
        END IF;
    ELSIF NEW.status <> 'pending' THEN
        RAISE EXCEPTION 'New entitlement must be pending';
    END IF;

    IF NEW.status = 'applied' AND (TG_OP = 'INSERT' OR OLD.status <> 'applied') THEN
        SELECT current_entitlement_sequence INTO last_sequence
        FROM platform_runtime.installations WHERE id = NEW.installation_id FOR UPDATE;
        IF NEW.sequence <= last_sequence THEN
            RAISE EXCEPTION 'Entitlement sequence % is not newer than %', NEW.sequence, last_sequence;
        END IF;
        UPDATE platform_runtime.installations
        SET current_entitlement_sequence = NEW.sequence, updated_at = now()
        WHERE id = NEW.installation_id;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION platform_runtime.protect_installation_identity()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Installation identity cannot be deleted';
    END IF;
    IF NEW.id IS DISTINCT FROM OLD.id
        OR NEW.singleton_key IS DISTINCT FROM OLD.singleton_key
        OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
        RAISE EXCEPTION 'Installation identity is immutable';
    END IF;
    IF NEW.current_entitlement_sequence < OLD.current_entitlement_sequence THEN
        RAISE EXCEPTION 'Entitlement sequence cannot decrease';
    END IF;
    RETURN NEW;
END;
$function$
